    public AS2InsufficientSecurityException(String message) {
        super(message);
    }

    @Override
    public AS2DispositionModifier getDispositionModifier() {
        return AS2DispositionModifier.ERROR_INSUFFICIENT_MESSAGE_SECURITY;
    }
}

